export { Radio } from './Radio';
export type { RadioGroupProps, RadioProps } from './Radio.types';
export { RadioGroup } from './RadioGroup';

import { forwardRef, useId } from 'react';

import { cn } from '../../utils';

import type { RadioProps } from './Radio.types';

/**
 * Radio Component
 *
 * A Bootstrap 5 radio button component for single-selection inputs.
 * Usually used within a RadioGroup for proper state management.
 *
 * @see https://getbootstrap.com/docs/5.3/forms/checks-radios/#radios
 *
 * @example
 * ```tsx
 * // Basic radio button
 * <Radio value="option1" label="Option 1" name="options" />
 *
 * // Within a RadioGroup (recommended)
 * <RadioGroup name="size" value={size} onChange={setSize}>
 *   <Radio value="sm" label="Small" />
 *   <Radio value="md" label="Medium" />
 *   <Radio value="lg" label="Large" />
 * </RadioGroup>
 * ```
 *
 * Accessibility Features (WCAG 2.2 AA):
 * - Native `<input type="radio">` for full keyboard support
 * - `<label>` properly associated with input
 * - Arrow key navigation (within RadioGroup)
 * - Minimum 44×44px touch target via Bootstrap styling
 */
export const Radio = forwardRef<HTMLInputElement, RadioProps>(
  (
    {
      value,
      label,
      checked,
      onChange,
      disabled = false,
      error = false,
      name,
      inline = false,
      reverse = false,
      className = '',
      style,
      id: providedId,
      required = false,
      'aria-label': ariaLabel,
      ...rest
    },
    ref
  ) => {
    // Generate unique ID if not provided
    const generatedId = useId();
    const id = providedId || generatedId;

    // Build wrapper classes
    const wrapperClasses = cn(
      'form-check',
      inline && 'form-check-inline',
      reverse && 'form-check-reverse',
      className
    );

    // Build input classes
    const inputClasses = cn('form-check-input', error && 'is-invalid');

    return (
      <div className={wrapperClasses} style={style}>
        <input
          ref={ref}
          type="radio"
          id={id}
          className={inputClasses}
          value={value}
          checked={checked}
          onChange={onChange}
          disabled={disabled}
          name={name}
          required={required}
          aria-label={!label ? ariaLabel : undefined}
          {...rest}
        />
        {label && (
          <label htmlFor={id} className="form-check-label">
            {label}
            {required && <span className="text-danger ms-1">*</span>}
          </label>
        )}
      </div>
    );
  }
);

Radio.displayName = 'Radio';

import type { CSSProperties, InputHTMLAttributes, ReactNode } from 'react';

/**
 * Radio button component props
 *
 * @see https://getbootstrap.com/docs/5.3/forms/checks-radios/#radios
 *
 * @example
 * ```tsx
 * // Basic radio button
 * <Radio value="option1" label="Option 1" name="options" />
 *
 * // Within a RadioGroup (recommended)
 * <RadioGroup name="size" value={size} onChange={setSize}>
 *   <Radio value="sm" label="Small" />
 *   <Radio value="md" label="Medium" />
 *   <Radio value="lg" label="Large" />
 * </RadioGroup>
 * ```
 */
export interface RadioProps
  extends Omit<InputHTMLAttributes<HTMLInputElement>, 'type' | 'onChange'> {
  /**
   * Radio button value (required for form submission)
   */
  value: string;

  /**
   * Radio button label
   */
  label?: ReactNode;

  /**
   * Checked state (controlled by RadioGroup or manually)
   */
  checked?: boolean;

  /**
   * Change handler
   */
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;

  /**
   * Disabled state
   * @default false
   */
  disabled?: boolean;

  /**
   * Error state - shows error styling
   * @default false
   */
  error?: boolean;

  /**
   * Form field name (usually provided by RadioGroup)
   */
  name?: string;

  /**
   * Display radio inline with others
   * @default false
   */
  inline?: boolean;

  /**
   * Reverse the order of label and radio
   * @default false
   */
  reverse?: boolean;

  /**
   * Additional CSS class names for the wrapper
   */
  className?: string;

  /**
   * Inline styles for the wrapper
   */
  style?: CSSProperties;

  /**
   * ID attribute for the input
   * Auto-generated if not provided
   */
  id?: string;

  /**
   * Required field indicator
   * @default false
   */
  required?: boolean;

  /**
   * Accessible label for screen readers (when no visible label)
   */
  'aria-label'?: string;
}

/**
 * RadioGroup component props
 *
 * Manages a group of Radio buttons with controlled or uncontrolled state.
 *
 * @example
 * ```tsx
 * // Controlled RadioGroup
 * const [value, setValue] = useState('option1');
 * <RadioGroup
 *   name="options"
 *   label="Select an option"
 *   value={value}
 *   onChange={(e) => setValue(e.target.value)}
 * >
 *   <Radio value="option1" label="Option 1" />
 *   <Radio value="option2" label="Option 2" />
 *   <Radio value="option3" label="Option 3" />
 * </RadioGroup>
 *
 * // Uncontrolled RadioGroup
 * <RadioGroup name="size" defaultValue="md" label="Size">
 *   <Radio value="sm" label="Small" />
 *   <Radio value="md" label="Medium" />
 *   <Radio value="lg" label="Large" />
 * </RadioGroup>
 * ```
 */
export interface RadioGroupProps {
  /**
   * Radio group children (Radio components)
   */
  children: ReactNode;

  /**
   * Form field name (required, shared by all radios)
   */
  name: string;

  /**
   * Controlled value
   */
  value?: string;

  /**
   * Default value for uncontrolled mode
   */
  defaultValue?: string;

  /**
   * Change handler for controlled mode
   */
  onChange?: (event: React.ChangeEvent<HTMLInputElement>) => void;

  /**
   * Group label (displayed above the radios)
   */
  label?: ReactNode;

  /**
   * Disable all radios in the group
   * @default false
   */
  disabled?: boolean;

  /**
   * Error state for the group
   * @default false
   */
  error?: boolean;

  /**
   * Helper text displayed below the group
   */
  helperText?: string;

  /**
   * Display radios inline
   * @default false
   */
  inline?: boolean;

  /**
   * Additional CSS class names
   */
  className?: string;

  /**
   * Inline styles
   */
  style?: CSSProperties;

  /**
   * Required field
   * @default false
   */
  required?: boolean;

  /**
   * ID for the group container
   */
  id?: string;
}

import { Children, cloneElement, isValidElement, type ReactElement, useId } from 'react';

import { useControllableState } from '../../hooks';
import { cn } from '../../utils';

import { Radio } from './Radio';

import type { RadioGroupProps, RadioProps } from './Radio.types';

/**
 * RadioGroup Component
 *
 * A Bootstrap 5 container for managing a group of Radio buttons.
 * Handles controlled and uncontrolled state, and provides proper
 * accessibility attributes for the radio group.
 *
 * @see https://getbootstrap.com/docs/5.3/forms/checks-radios/#radios
 *
 * @example
 * ```tsx
 * // Controlled RadioGroup
 * const [value, setValue] = useState('option1');
 * <RadioGroup
 *   name="options"
 *   label="Select an option"
 *   value={value}
 *   onChange={(e) => setValue(e.target.value)}
 * >
 *   <Radio value="option1" label="Option 1" />
 *   <Radio value="option2" label="Option 2" />
 *   <Radio value="option3" label="Option 3" />
 * </RadioGroup>
 *
 * // Uncontrolled RadioGroup
 * <RadioGroup name="size" defaultValue="md" label="Size">
 *   <Radio value="sm" label="Small" />
 *   <Radio value="md" label="Medium" />
 *   <Radio value="lg" label="Large" />
 * </RadioGroup>
 * ```
 *
 * Accessibility Features (WCAG 2.2 AA):
 * - `role="radiogroup"` for screen readers
 * - `aria-labelledby` for group label
 * - `aria-describedby` for helper text
 * - `aria-invalid` for error state
 * - Arrow key navigation between radios
 */
export function RadioGroup({
  children,
  name,
  value,
  defaultValue,
  onChange,
  label,
  disabled = false,
  error = false,
  helperText,
  inline = false,
  className = '',
  style,
  required = false,
  id: providedId,
}: RadioGroupProps): React.JSX.Element {
  // Generate unique IDs
  const generatedId = useId();
  const groupId = providedId || generatedId;
  const labelId = label ? `${groupId}-label` : undefined;
  const helperId = helperText ? `${groupId}-helper` : undefined;

  // Controllable state - wrap onChange to handle ChangeEvent
  const [currentValue, setCurrentValue] = useControllableState({
    value,
    defaultValue,
    onChange: (_newValue: string, event?: unknown) => {
      if (event && onChange && typeof event === 'object' && event !== null) {
        onChange(event as React.ChangeEvent<HTMLInputElement>);
      }
    },
  });

  // Handle change - pass both value and event to setCurrentValue
  const handleChange = (event: React.ChangeEvent<HTMLInputElement>): void => {
    setCurrentValue(event.target.value, event);
  };

  // Build wrapper classes
  const wrapperClasses = cn(inline && 'd-flex flex-wrap gap-3', className);

  // Clone children and inject props
  const enhancedChildren = Children.map(children, (child) => {
    if (isValidElement(child) && child.type === Radio) {
      const radioChild = child as ReactElement<RadioProps>;
      return cloneElement(radioChild, {
        name,
        checked: radioChild.props.value === currentValue,
        onChange: handleChange,
        disabled: disabled || radioChild.props.disabled,
        error: error || radioChild.props.error,
        inline,
      });
    }
    return child;
  });

  // Build helper text classes
  const helperClasses = cn(error ? 'invalid-feedback d-block' : 'form-text');

  return (
    <fieldset className={className} style={style} id={groupId}>
      {label && (
        <legend id={labelId} className="form-label">
          {label}
          {required && <span className="text-danger ms-1">*</span>}
        </legend>
      )}
      <div
        role="radiogroup"
        aria-labelledby={labelId}
        aria-describedby={helperId}
        aria-invalid={error || undefined}
        aria-required={required || undefined}
        className={wrapperClasses}
      >
        {enhancedChildren}
      </div>
      {helperText && (
        <div id={helperId} className={helperClasses}>
          {helperText}
        </div>
      )}
    </fieldset>
  );
}

RadioGroup.displayName = 'RadioGroup';
